#include "ec.hpp"
#include <filesystem>
#include <sys/resource.h>
#include <time.h>
extern "C" {
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wpedantic"
#include "../upstream/include/cryptanalysis/ca_bsgs.h"
#include "../upstream/include/cryptanalysis/ca_rho.h"
#pragma GCC diagnostic pop
}
constexpr U M=134217728;
U cpu_ns(){timespec t{};clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t);return U(t.tv_sec)*1000000000ULL+U(t.tv_nsec);}
json usage(){rusage r{};getrusage(RUSAGE_SELF,&r);return {{"user_us",U(r.ru_utime.tv_sec)*1000000+U(r.ru_utime.tv_usec)},{"system_us",U(r.ru_stime.tv_sec)*1000000+U(r.ru_stime.tv_usec)},{"max_rss_kib",r.ru_maxrss},{"minor_faults",r.ru_minflt},{"major_faults",r.ru_majflt},{"voluntary_switches",r.ru_nvcsw},{"involuntary_switches",r.ru_nivcsw}};}
void atomic(const std::string&f,const json&j){need(!std::filesystem::exists(f),"refuse overwrite "+f);save(f+".tmp",j);std::filesystem::rename(f+".tmp",f);}
json metrics(int status,U x,const ca_stats&s,U wall,U cpu,const json&before){return {{"status",status},{"recovered_k",std::to_string(x)},{"native_wall_ns",wall},{"native_process_cpu_ns",cpu},{"native_stats",{{"group_ops",s.group_ops},{"iterations",s.iterations},{"table_entries",s.table_entries},{"collisions",s.collisions},{"bytes_peak",s.bytes_peak},{"seconds",s.seconds},{"threads",s.threads}}},{"resources_before",before},{"resources_after",usage()},{"field_counters",nullptr},{"full_event_stream_collected",false}};}
void encode(const ca_group&g,ca_elem&target,Point P){U w[4]={P.x,P.y,0,0};need(ca_group_encode(&g,&target,w),"native encode");}
int main(int argc,char**argv){try{need(argc==5,"ROOT rho|bsgs OFFSET STRIDE");std::string root=argv[1],alg=argv[2];int offset=std::stoi(argv[3]),stride=std::stoi(argv[4]);need(offset>=0&&offset<stride&&(alg=="rho"||alg=="bsgs"),"worker args");auto family=load(root+"/data/family.json"),fixtures=load(root+"/data/fixtures.json"),binding=load(root+"/FROZEN.json");int completed=0,failed=0;
 for(int cid=0;cid<46;cid++){auto node=family["nodes"][cid];EC ec{val(node["a"]),val(node["b"])};auto rows=fixtures[std::to_string(cid)];for(int unit=0;unit<(alg=="rho"?100:10);unit++){int task=cid*(alg=="rho"?100:10)+unit;if(task%stride!=offset)continue;if(std::filesystem::exists(root+"/STOP")){std::cout<<"STOP acknowledged\n";return 0;}std::string job=root+"/runs/"+alg+"/C"+std::to_string(cid)+(alg=="rho"?"_I":"_G")+std::to_string(unit);std::filesystem::create_directories(job);if(std::filesystem::exists(job+"/complete.json")){auto old=load(job+"/complete.json");need(old["binding"]==binding&&old["verified"]==true,"checkpoint identity");completed++;continue;}std::string attempt=job+"/attempt_"+std::to_string(ns())+"_"+std::to_string(getpid());std::filesystem::create_directories(attempt);atomic(attempt+"/input.json",{{"curve",cid},{"unit",unit},{"algorithm",alg},{"binding",binding},{"offset",offset},{"stride",stride}});U batch=ns();ca_group g{};need(ca_group_ec_init(&g,PRIME,ec.a,ec.b,ORDER)==CA_OK,"native curve");g.cofactor=4;ca_elem base,target;ca_bsgs_table*table=nullptr;json records=json::array();U setupWall=0;int setupStatus=0;
 if(alg=="bsgs"){encode(g,base,point(rows[unit*10]["P"]));auto before=usage();U t=ns(),c=cpu_ns();setupStatus=ca_bsgs_table_new(&g,&base,M,&table);U cpu=cpu_ns()-c;setupWall=ns()-t;atomic(attempt+"/setup.json",{{"status",setupStatus},{"native_wall_ns",setupWall},{"native_process_cpu_ns",cpu},{"nominal_setup_group_ops",M},{"resources_before",before},{"resources_after",usage()}});}
 bool all=setupStatus==0;int first=alg=="rho"?unit:unit*10,last=alg=="rho"?unit+1:unit*10+10;
 if(all)for(int id=first;id<last;id++){auto row=rows[id];Point P=point(row["P"]),Q=point(row["Q"]);encode(g,base,P);encode(g,target,Q);ca_stats st{};U x=0;auto before=usage();U t=ns(),c=cpu_ns();int rc;if(alg=="rho"){ca_rho_params par;ca_rho_params_default(&par);par.seed=val(row["rho_seed"]);par.threads=1;par.max_ops=2000000000ULL;par.max_table_entries=1000000;rc=ca_rho_solve(&g,&base,&target,&par,&x,&st);}else rc=ca_bsgs_table_solve(table,&target,0,0,&x,&st);U cpu=cpu_ns()-c,wall=ns()-t;auto result=metrics(rc,x,st,wall,cpu,before);t=ns();bool equation=rc==0&&ec.scalar(x,P)==Q;auto expected=load(root+"/data/checker_answers.json");bool expectedMatches=x==val(expected[id]["k"]);result["external_verification_ns"]=ns()-t;result["verified"]=equation&&expectedMatches;result["curve"]=cid;result["level"]=node["level"];result["instance"]=id;result["generator"]=row["generator"];result["key_index"]=row["key_index"];result["point_order"]=row["point_order"];result["target_order"]=row["target_order"];result["rho_seed"]=alg=="rho"?row["rho_seed"]:json(nullptr);result["expected_scalar_passed_to_solver"]=false;result["setup_excluded_from_query"]=alg=="bsgs";if(alg=="bsgs"){result["derived_setup_plus_query_ns"]=setupWall+wall;result["derived_setup_plus_query_group_ops"]=M+st.group_ops;need(rc!=0||(st.iterations==x/M+1&&st.group_ops==x/M),"BSGS search identity");}atomic(attempt+"/case_"+std::to_string(id)+".json",result);records.push_back(result);all=all&&equation&&expectedMatches;std::cout<<alg<<" C"<<cid<<" I"<<id<<" status="<<rc<<" verified="<<(equation&&expectedMatches)<<" ops="<<st.group_ops<<" wall_s="<<double(wall)/1e9<<std::endl;}
 if(table){U t=ns();ca_bsgs_table_free(table);atomic(attempt+"/destruction.json",{{"wall_ns",ns()-t}});}json complete={{"binding",binding},{"verified",all},{"curve",cid},{"unit",unit},{"algorithm",alg},{"attempt",std::filesystem::path(attempt).filename().string()},{"batch_wall_ns",ns()-batch},{"records",records},{"resources_end",usage()}};atomic(attempt+"/result.json",complete);if(all){atomic(job+"/complete.json",complete);completed++;}else failed++;}}
 std::cout<<"FINISHED "<<alg<<" partition="<<offset<<"/"<<stride<<" completed="<<completed<<" failed="<<failed<<std::endl;return failed?2:0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
